```xml
// Running mvn package on this pom.xml
<project>
  <groupId>com.example</groupId>
  <artifactId>customer-service</artifactId>
  <version>2.1.0-SNAPSHOT</version>
  <packaging>jar</packaging>

  <dependencies>
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-web</artifactId>
    </dependency>
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-test</artifactId>
      <scope>test</scope>
    </dependency>
  </dependencies>
</project>

// What happens when you run: mvn package
// Phase 1: validate - checks pom.xml is valid
// Phase 2: compile - compiles src/main/java/*.java to target/classes/
// Phase 3: test-compile - compiles src/test/java/*.java to target/test-classes/
// Phase 4: test - runs JUnit tests using maven-surefire-plugin
// Phase 5: package - creates target/customer-service-2.1.0-SNAPSHOT.jar

// The resulting JAR is ready to run but NOT installed to local repo yet
// To install: mvn install
// This runs all phases through package, then install phase
// Copies JAR to ~/.m2/repository/com/example/customer-service/2.1.0-SNAPSHOT/

// To deploy to remote Nexus: mvn deploy
// Runs everything including install, then uploads to configured remote repo
```

```java
// Project structure for examples
// order-service/
//   src/main/java/com/example/OrderService.java
//   src/test/java/com/example/OrderServiceTest.java
//   pom.xml

// Command 1: Clean the project
$ mvn clean
// Output: Deletes target/ directory
// [INFO] --- maven-clean-plugin:3.2.0:clean (default-clean) @ order-service ---
// [INFO] Deleting /path/to/order-service/target

// Command 2: Compile source code only
$ mvn compile
// Output: Creates target/classes/ with .class files
// [INFO] --- maven-compiler-plugin:3.11.0:compile (default-compile) @ order-service ---
// [INFO] Compiling 5 source files to /path/to/order-service/target/classes

// Command 3: Run tests (also compiles if needed)
$ mvn test
// Runs validate → compile → test-compile → test
// [INFO] --- maven-surefire-plugin:3.0.0:test (default-test) @ order-service ---
// [INFO] Running com.example.OrderServiceTest
// [INFO] Tests run: 8, Failures: 0, Errors: 0, Skipped: 0

// Command 4: Create JAR (most common for development)
$ mvn package
// Runs all phases through package, creates target/order-service-1.0.0.jar

// Command 5: Install to local repo for other modules to use
$ mvn install
// Copies JAR to ~/.m2/repository/com/example/order-service/1.0.0/

// Command 6: Diagnostic command for dependency issues
$ mvn dependency:tree
// Shows all dependencies including transitive ones
// [INFO] com.example:order-service:jar:1.0.0
// [INFO] +- org.springframework.boot:spring-boot-starter-web:jar:3.2.0
// [INFO] |  +- org.springframework.boot:spring-boot-starter-json:jar:3.2.0
// [INFO] |  |  \- com.fasterxml.jackson.core:jackson-databind:jar:2.15.3
